* { box-sizing: border-box; }
body { margin: 0; background: #f5f6f8; color: #1c2535; font-family: system-ui, sans-serif; }
.workflow-app { max-width: 1100px; margin: auto; padding: 40px 28px; }
.workflow-heading, .workflow-pagination { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.workflow-eyebrow { font-size: 11px; letter-spacing: .16em; color: #57657b; font-weight: 700; }
.workflow-heading h1 { margin: 8px 0 28px; font-size: clamp(24px, 4vw, 36px); letter-spacing: -.035em; }
.workflow-mode { font-size: 12px; color: #57657b; }
.workflow-app nav { display: flex; gap: 6px; padding-bottom: 20px; flex-wrap: wrap; }
.workflow-app button { cursor: pointer; font: inherit; border: 1px solid #cdd4df; padding: 9px 14px; background: white; border-radius: 6px; color: inherit; }
.workflow-app button:disabled { opacity: .5; cursor: default; }
.workflow-app button[aria-current="page"] { background: #213957; color: white; border-color: #213957; }
.workflow-app :focus-visible { outline: 3px solid #3479c9; outline-offset: 3px; }
.workflow-toolbar { display: flex; gap: 16px; flex-wrap: wrap; align-items: end; margin: 0 0 24px; }
.workflow-app label { display: flex; flex-direction: column; gap: 6px; font-size: 13px; }
.workflow-app input:not([type="checkbox"]), .workflow-app select { font: inherit; max-width: 100%; border: 1px solid #cdd4df; border-radius: 5px; padding: 10px; background: white; }
.workflow-content { padding: 24px; border: 1px solid #dce1e8; border-radius: 12px; background: white; min-width: 0; overflow-wrap: anywhere; }
.workflow-field { margin-bottom: 20px; }
.workflow-content [data-layout="inline"] { flex-wrap: wrap; gap: 12px; }
.workflow-content [data-layout="inline"] > [data-oods-component="SearchInput"], .workflow-content [data-layout="inline"] > [data-oods-component="Select"] { flex: 1 1 180px; min-width: 0; }
.workflow-content [data-oods-component="PriceBadge"] { white-space: nowrap; }
.workflow-content textarea { font: inherit; border: 1px solid #cdd4df; border-radius: 5px; padding: 10px; }
.workflow-content [data-oods-component="Stack"], .workflow-content [data-oods-component="Tabs"] { min-width: 0; }
.workflow-content .oods-tab, .workflow-content .oods-tab-list [aria-haspopup="menu"] { flex-shrink: 0; white-space: nowrap; }
.workflow-content .oods-tab-list { overflow: visible; }
.workflow-content .oods-tabs__overflow, .workflow-content .oods-tabs-overflow { position: relative; flex-shrink: 0; }
.workflow-content .oods-tab-list [role="menu"] { position: absolute; inset: 100% 0 auto auto; z-index: 2; min-width: max-content; display: grid; padding: 4px; background: white; border: 1px solid #dce1e8; border-radius: 6px; }

.workflow-cancel { display: flex; gap: 16px; flex-wrap: wrap; border: 1px solid #dce1e8; padding: 16px; margin: 0 0 24px; border-radius: 6px; }
.workflow-records { padding: 0; list-style: none; margin: 24px 0; }
.workflow-records li + li { margin-top: 8px; }
.workflow-records button { width: 100%; display: grid; grid-template-columns: 1fr auto 20px; gap: 16px; text-align: left; padding: 18px; }
.workflow-records span { color: #57657b; font-size: 13px; }
.workflow-history { padding-left: 24px; }
.workflow-history li { padding: 8px 0 20px 12px; }
.workflow-history time { display: block; color: #57657b; font-size: 12px; margin: 8px 0; }
.workflow-notice { min-height: 20px; color: #57657b; font-size: 13px; }
[data-oods-screen-actions] { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 24px; }
@media (max-width: 600px) { .workflow-content [data-layout="sidebar"] { grid-template-columns: minmax(0, 1fr) !important; } .workflow-app { padding: 24px 16px; } .workflow-content { padding: 16px; } .workflow-mode { display: none; } .workflow-toolbar > label { flex: 1 1 140px; } .workflow-records button { grid-template-columns: minmax(0, 1fr); gap: 10px; } .workflow-records button > [data-oods-component="StatusBadge"] { justify-self: start; max-width: 100%; } .workflow-records button > span:last-child { display: none; } }

import { parseBillingAmount } from '@oods/component-contracts';
import { createStore, idField, titleField, fieldTypes, screenProps, history, type DomainRecord, type ListQuery, type StoreOptions } from './store';
import { sampleData } from './sample-data';
import type { WorkflowActions } from './actions';
export { idField, titleField, screenProps, history };
export type Screen = 'list' | 'detail' | 'form' | 'timeline';
export type UIState = 'loading' | 'empty' | 'error' | 'success';
export const routes = {"list":"/","detail":"/:id","form":"/:id/edit","timeline":"/:id/timeline"};
export const cancellable = true;
export const statuses = ["future","trialing","active","paused","pending_cancellation","past_due","unpaid","terminated"];
export const archivePresentation = {"archivedField":"is_archived","showBadge":true,"separateTab":true,"tabLabel":"Archived"};
export const supplementalFields = [{"name":"plan_name","label":"Human-readable plan label shown in headers."}];
const fieldByNodeId: Record<string, string> = {"list-slot-filters-2":"cancel_at_period_end","list-ve-items-10":"status","list-ve-items-11":"updated_at","detail-ve-header-26":"status","detail-slot-tab-3-15":"payment_status","detail-slot-tab-4-17":"amount","form-ve-title-28":"status","form-ve-field-0-26":"billing_interval","form-ve-field-0-27":"amount","form-slot-field-1-5":"cancel_at_period_end","form-slot-field-2-7":"cancellation_reason","form-slot-field-3-13":"cancellation_requested_at","form-slot-field-4-15":"currency","form-slot-field-5-17":"payment_method_type","form-slot-field-6-19":"customer_email","form-slot-field-7-21":"last_event","form-slot-field-8-23":"amount","form-slot-field-9-25":"billing_interval","timeline-slot-header-2":"amount"};
export interface AppState { screen: Screen; uiState: UIState; id: string; draft: DomainRecord; records: DomainRecord[]; total: number; page: number; archived: boolean; error: string; notice: string; revision: number }
export function createWorkflow(options: StoreOptions = {}) {
  const store = createStore(options);
  let query: ListQuery = {};
  let request = 0;
  const first = store.list().records[0] ?? sampleData[0]!;
  let state: AppState = { screen: 'list', uiState: 'loading', id: String(first[idField]), draft: structuredClone(first), records: [], total: 0, page: 1, archived: false, error: '', notice: '', revision: 0 };
  const listeners = new Set<(state: AppState) => void>();
  const publish = (patch: Partial<AppState>) => { state = { ...state, ...patch }; listeners.forEach((listener) => listener(state)); };
  const value = (field: string) => (state.draft as Record<string, unknown>)[field];
  async function navigate(screen: Screen, id = state.id) {
    const ticket = ++request;
    publish({ screen, id, uiState: 'loading', error: '', revision: state.revision + 1 });
    try {
      await store.ready();
      if (ticket !== request) return;
      const list = store.list(query);
      const selected = screen === 'list' ? list.records[0] : store.list({ archived: query.archived, pageSize: 10000 }).records.find((record) => String(record[idField]) === id);
      const draft = selected ?? sampleData[0]!;
      publish({ records: list.records, total: list.total, page: list.page, archived: query.archived ?? false, draft: structuredClone(draft), id: selected ? String(selected[idField]) : id, uiState: selected ? 'success' : 'empty' });
    } catch (error) { if (ticket === request) publish({ uiState: 'error', error: error instanceof Error ? error.message : String(error) }); }
  }
  async function change(operation: () => DomainRecord, destination: Screen) {
    publish({ uiState: 'loading', error: '' });
    try { await store.ready(); operation(); publish({ notice: 'Changes saved in this session.' }); await navigate(destination); }
    catch (error) { publish({ uiState: 'error', error: error instanceof Error ? error.message : String(error) }); }
  }
  const actions: WorkflowActions = {
    handleCancel: () => { void change(() => store.cancel(state.id, String(value("cancellation_reason") ?? ""), String(value("cancellation_reason_code") ?? ""), Boolean(value("cancel_at_period_end"))), "detail"); },
    handleChange: () => { publish({ notice: "Changes are ready to save." }); },
    handleDelete: () => { void change(() => store.archive(state.id), "list"); },
    handleEdit: () => { void navigate("form"); },
    handleFilter: (criteria) => { query = { ...query, search: String(criteria.search ?? ""), status: String(criteria.status ?? ""), page: 1 }; void navigate("list"); },
    handleRowClick: (id) => { void navigate("detail", id); },
    handleSort: (column) => { if (column in fieldTypes) { query = { ...query, sort: column as keyof DomainRecord, descending: !query.descending }; void navigate("list"); } },
    handleSubmit: () => { void change(() => store.save(state.draft), "detail"); },
    handleViewTimeline: () => { void navigate("timeline"); },
  };
  function edit(event: Event) {
    if (state.screen !== 'form' && state.screen !== 'detail') return;
    const target = event.target;
    if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement || target instanceof HTMLTextAreaElement)) return;
    let field = target.name;
    let element: HTMLElement | null = target;
    while (!Object.hasOwn(fieldTypes, field) && element) { field = fieldByNodeId[element.id] ?? ''; element = element.parentElement; }
    if (!Object.hasOwn(fieldTypes, field)) return;
    const type = fieldTypes[field];
    if (target instanceof HTMLInputElement && target.dataset.billingMinorUnits !== undefined) {
      const result = parseBillingAmount(target.value, Number(target.dataset.billingMinorUnits));
      if (result.valid) publish({ draft: { ...state.draft, [field]: result.value }, notice: 'Unsaved changes' });
      return;
    }
    const value = target instanceof HTMLInputElement && target.type === 'checkbox' ? target.checked
      : type === 'number' || type === 'integer' ? Number(target.value) : target.value;
    publish({ draft: { ...state.draft, [field]: value }, notice: 'Unsaved changes' });
  }
  return {
    snapshot: () => state,
    subscribe(listener: (state: AppState) => void) { listeners.add(listener); return () => { listeners.delete(listener); }; },
    navigate, actions, edit,
    filter(search: string, status = query.status ?? '') { query = { ...query, search, status, page: 1 }; return navigate('list'); },
    sort(descending: boolean) { query = { ...query, sort: titleField, descending }; return navigate('list'); },
    page(page: number) { query = { ...query, page }; return navigate('list'); },
    archived(archived: boolean) { query = { ...query, archived, page: 1 }; return navigate('list'); },
    restore() { return change(() => store.restore(state.id), 'list'); },
    retry() { store.setFailure(false); return navigate(state.screen); },
    dispose() { request++; listeners.clear(); },
  };
}

import { createApp, createSSRApp } from 'vue';
import App from './App.vue';
const query = new URLSearchParams(window.location.search);
const root = document.getElementById('app')!;
(root.hasChildNodes() ? createSSRApp : createApp)(App, { empty: query.get('mode') === 'empty', fail: query.get('mode') === 'error', latency: Number(query.get('latency') ?? 180) }).mount('#app');

import { createSSRApp } from 'vue';
import { renderToString } from '@vue/server-renderer';
import App from './App.vue';
import type { StoreOptions } from './store';
export function renderApp(options: StoreOptions = {}) { return renderToString(createSSRApp(App, { ...options })); }

import { sampleData } from './sample-data';

export type DomainRecord = {
  "status": 'future' | 'trialing' | 'active' | 'paused' | 'pending_cancellation' | 'past_due' | 'unpaid' | 'terminated';
  "state_history": unknown[];
  "allowed_transitions": string[];
  "cancel_at_period_end": boolean;
  "cancellation_reason": string;
  "cancellation_reason_code": string;
  "cancellation_requested_at": string;
  "created_at": string;
  "updated_at": string;
  "last_event": string;
  "last_event_at": string;
  "amount": number;
  "currency": string;
  "billing_interval": string;
  "payment_status": 'pending' | 'succeeded' | 'failed' | 'retrying' | 'refunded';
  "payment_method_type": 'card' | 'ach' | 'wire' | 'invoice' | 'other';
  "proration_amount": number;
  "proration_date": number;
  "last_payment_at": string;
  "next_payment_due_at": string;
  "current_period_start": string;
  "current_period_end": string;
  "current_period_progress": number;
  "is_archived": boolean;
  "archived_at": string | null;
  "restored_at": string | null;
  "archive_reason": string;
  "archived_by": string;
  "archive_metadata": Record<string, unknown>;
  "restoration_metadata": Record<string, unknown>;
  "subscription_id": string;
  "plan_name": string;
  "plan_code": string;
  "plan_interval": string;
  "customer_name": string;
  "customer_email": string;
};
export const idField = "subscription_id" as const;
export const titleField = "plan_name" as const;
export const fieldTypes: Record<string, string> = {"status":"string","state_history":"StateTransition[]","allowed_transitions":"string[]","cancel_at_period_end":"boolean","cancellation_reason":"string","cancellation_reason_code":"string","cancellation_requested_at":"datetime","created_at":"datetime","updated_at":"datetime","last_event":"string","last_event_at":"datetime","amount":"integer","currency":"string","billing_interval":"string","payment_status":"string","payment_method_type":"string","proration_amount":"integer","proration_date":"integer","last_payment_at":"datetime","next_payment_due_at":"datetime","current_period_start":"datetime","current_period_end":"datetime","current_period_progress":"number","is_archived":"boolean","archived_at":"datetime?","restored_at":"datetime?","archive_reason":"string","archived_by":"string","archive_metadata":"object","restoration_metadata":"object","subscription_id":"string","plan_name":"string","plan_code":"string","plan_interval":"string","customer_name":"string","customer_email":"email"};
export const traits: readonly string[] = ["Stateful","Cancellable","Timestampable","Billable","Archivable"];
export interface StoreOptions { empty?: boolean; fail?: boolean; latency?: number; now?: () => string; seed?: DomainRecord[] }
export interface ListQuery { search?: string; status?: string; archived?: boolean; sort?: keyof DomainRecord; descending?: boolean; page?: number; pageSize?: number }
export interface HistoryEntry { from: string | null; to: string; at: string; reason: string; code?: string; atPeriodEnd?: boolean }
export function screenProps(record: DomainRecord) {
  return {
  status: record["status"],
  stateHistory: record["state_history"],
  allowedTransitions: record["allowed_transitions"],
  cancelAtPeriodEnd: record["cancel_at_period_end"],
  cancellationReason: record["cancellation_reason"],
  cancellationReasonCode: record["cancellation_reason_code"],
  cancellationRequestedAt: record["cancellation_requested_at"],
  createdAt: record["created_at"],
  updatedAt: record["updated_at"],
  lastEvent: record["last_event"],
  lastEventAt: record["last_event_at"],
  amount: record["amount"],
  currency: record["currency"],
  billingInterval: record["billing_interval"],
  paymentStatus: record["payment_status"],
  paymentMethodType: record["payment_method_type"],
  prorationAmount: record["proration_amount"],
  prorationDate: record["proration_date"],
  lastPaymentAt: record["last_payment_at"],
  nextPaymentDueAt: record["next_payment_due_at"],
  currentPeriodStart: record["current_period_start"],
  currentPeriodEnd: record["current_period_end"],
  currentPeriodProgress: record["current_period_progress"],
  isArchived: record["is_archived"],
  archivedAt: record["archived_at"],
  restoredAt: record["restored_at"],
  archiveReason: record["archive_reason"],
  archivedBy: record["archived_by"],
  archiveMetadata: record["archive_metadata"],
  restorationMetadata: record["restoration_metadata"],
  subscriptionId: record["subscription_id"],
  planName: record["plan_name"],
  planCode: record["plan_code"],
  planInterval: record["plan_interval"],
  customerName: record["customer_name"],
  customerEmail: record["customer_email"],
  };
}
export function history(record: DomainRecord): HistoryEntry[] {
  const value = (record as Record<string, unknown>).state_history;
  return Array.isArray(value) ? value.filter((entry): entry is HistoryEntry => !!entry && typeof entry === 'object' && typeof entry.to === 'string' && typeof entry.at === 'string') : [];
}
export function createStore(options: StoreOptions = {}) {
  let records = structuredClone(options.seed ?? (options.empty ? [] : sampleData));
  let fail = options.fail ?? false;
  const now = options.now ?? (() => new Date().toISOString());
  const requireTrait = (trait: string) => { if (!traits.includes(trait)) throw new Error('Object does not support ' + trait); };
  const get = (id: string) => {
    const record = records.find((entry) => String(entry[idField]) === id);
    if (!record) throw new Error('Record not found: ' + id);
    return structuredClone(record);
  };
  const save = (record: DomainRecord) => {
    const index = records.findIndex((entry) => entry[idField] === record[idField]);
    if (index < 0) throw new Error('Cannot save a missing record');
    records[index] = structuredClone(record);
    return get(String(record[idField]));
  };
  const setArchived = (id: string, archived: boolean) => {
    requireTrait('Archivable');
    const record = get(id);
    Object.assign(record, { is_archived: archived, archived_at: archived ? now() : null });
    return save(record);
  };
  return {
    get, save,
    async ready() {
      await new Promise<void>((resolve) => setTimeout(resolve, Math.max(0, options.latency ?? 180)));
      if (fail) throw new Error('Simulated data service failure');
    },
    setFailure(value: boolean) { fail = value; },
    list(query: ListQuery = {}) {
      const search = (query.search ?? '').trim().toLowerCase();
      const filtered = records.filter((record) => {
        const values = record as Record<string, unknown>;
        return Boolean(values.is_archived) === (query.archived ?? false)
          && (!query.status || values.status === query.status)
          && (!search || Object.values(record).some((value) => String(value).toLowerCase().includes(search)));
      });
      const sort = query.sort ?? titleField;
      filtered.sort((a, b) => {
        const left = a[sort]; const right = b[sort];
        const order = typeof left === 'number' && typeof right === 'number' ? left - right : String(left).localeCompare(String(right));
        return (query.descending ? -1 : 1) * order;
      });
      const pageSize = Math.max(1, Math.floor(query.pageSize ?? 10));
      const page = Math.max(1, Math.floor(query.page ?? 1));
      return { total: filtered.length, page, pageSize, records: structuredClone(filtered.slice((page - 1) * pageSize, page * pageSize)) };
    },
    cancel(id: string, reason: string, code: string, atPeriodEnd: boolean) {
      requireTrait('Cancellable');
      const record = get(id);
      const values = record as Record<string, unknown>;
      if (values.is_archived || values.status === 'terminated' || values.status === 'pending_cancellation') throw new Error('This record cannot be cancelled in its current state');

      const at = now();
      const entry: HistoryEntry = { from: String(values.status), to: 'pending_cancellation', at, reason: reason.trim(), code, atPeriodEnd };
      Object.assign(record, { status: 'pending_cancellation', cancellation_reason: reason.trim(), cancellation_reason_code: code, cancel_at_period_end: atPeriodEnd, cancellation_requested_at: at, state_history: [...history(record), entry], updated_at: at });
      return save(record);
    },
    archive(id: string) { return setArchived(id, true); },
    restore(id: string) { return setArchived(id, false); },
  };
}
